            "svgUrdu": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 337 110\" role=\"img\" aria-label=\"Equation 7.7: or   stress = (\u0001)/(\u0002)\"><g font-family=\"sans-serif\" font-size=\"25\" fill=\"currentColor\"><text x=\"5.0\" y=\"64\">or   stress = </text><text x=\"207.2\" y=\"34\" text-anchor=\"middle\">F</text><text x=\"207.2\" y=\"92\" text-anchor=\"middle\">A</text><path d=\"M195.4 54h23.6\" stroke=\"currentColor\" stroke-width=\"2\"/><rect x=\"255.0\" y=\"35.0\" width=\"72\" height=\"40\" rx=\"4\" fill=\"#3e899d\"/><text x=\"291.0\" y=\"64.0\" text-anchor=\"middle\" fill=\"#fff\">7.7</text></g></svg>",
            "svgPashto": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 337 110\" role=\"img\" aria-label=\"Equation 7.7: or   stress = (\u0001)/(\u0002)\"><g font-family=\"sans-serif\" font-size=\"25\" fill=\"currentColor\"><text x=\"5.0\" y=\"64\">or   stress = </text><text x=\"207.2\" y=\"34\" text-anchor=\"middle\">F</text><text x=\"207.2\" y=\"92\" text-anchor=\"middle\">A</text><path d=\"M195.4 54h23.6\" stroke=\"currentColor\" stroke-width=\"2\"/><rect x=\"255.0\" y=\"35.0\" width=\"72\" height=\"40\" rx=\"4\" fill=\"#3e899d\"/><text x=\"291.0\" y=\"64.0\" text-anchor=\"middle\" fill=\"#fff\">7.7</text></g></svg>",
