  if (freshReviewed.length === reviewed.length && freshReviewed.some(page => page.chapterEnd)) chapter.pageRange = `Pages ${reviewed[0].printedPage} – ${(reviewed.find(page => page.chapterEnd) || reviewed.at(-1)).printedPage}`;
