      section.paras.push(...fragment.paras.slice(continues ? 1 : 0).map(para => typeof para === 'string' ? para : {...para}));
      section.sourceBlocks.push(...(fragment.blocks || []));
      section.personNames.push(...(fragment.personNames || []));
