    section.diagramSvg += section.sourceBlocks.filter(block => block.type === 'dataTable').flatMap(table => (table.translations || []).map(translation => `<details dir="rtl"><summary>${translation.language}</summary><div style="overflow-x:auto"><table class="diff-table"><thead><tr>${table.noHeader ? '' : translation.headers.map(header => `<th>${header}</th>`).join('')}</tr></thead><tbody>${translation.rows.map(row => `<tr>${row.map(cell => `<td>${sourceTableCell(cell, translation.language)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`)).join('');
    if (existing) Object.assign(existing, section);
    else chapter.sections.unshift(section);
