    formula.sourceBlockIds = link.blockIds;
    formula.sourceReferences = sources.map(({sourcePage}) => ({sourcePdf:sourcePage.sourcePdf,pdfPage:sourcePage.pdfPage,printedPage:sourcePage.printedPage}));
